    15	 * it checks if the child's tagName is 'emoji'. If it is, it creates an EmojiWithTooltip component
    16	 * with the appropriate styles and adds it to the elements array. If it's not, it adds the child's
    17	 * 'data' property to the elements array. The function then returns the elements array.
    18	 *
    19	 * @param defaultRendererProps - The default renderer props.
    20	 * @param textStyles - The text styles.
    21	 * @param styles - The theme styles.
    22	 * @returns The array of elements to be rendered.
    23	 */
    24	function renderElements(defaultRendererProps: TDefaultRendererProps<TTextOrTPhrasing>, textStyles: StyleProp<TextStyle>, styles: ThemeStyles) {
    25	    const elements: Array<string | React.JSX.Element> = [];
    26	
    27	    if ('data' in defaultRendererProps.tnode) {
    28	        elements.push(defaultRendererProps.tnode.data);
    29	        return elements;
    30	    }
    31	
    32	    if (!defaultRendererProps.tnode.children) {
    33	        return elements;
    34	    }
    35	
